{"path":"app/analytics.ts","content":"import 'server-only'

/** Send a page view to the configured analytics service. */
export async function logPageView(path: string): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT
  if (!endpoint) return

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(process.env.ANALYTICS_API_KEY
        ? { Authorization: `Bearer ${process.env.ANALYTICS_API_KEY}` }
        : {}),
    },
    body: JSON.stringify({ event: 'page_view', path }),
  })

  if (!response.ok) {
    throw new Error(`Analytics service returned HTTP ${response.status}`)
  }
}
"}

